-- Catalogo CPT (Procedural Terminology) 2026 para Latinoamerica
-- Generado a partir de: CMS PFS RVU26A (PPRRVU2026_Jan_nonQPP.csv, release 12/29/2025)
-- https://www.cms.gov/medicare/payment/fee-schedules/physician/pfs-relative-value-files
--
-- NOTA: Los codigos, RVUs y estados provienen de datos publicos de CMS. Los descriptores
-- en espanol latinoamericano (short/medium/long) y los Lay Terms son traducciones
-- automaticas generadas con diccionario medico propio (metodo: traduccion asistida,
-- NO son traducciones oficiales de la AMA). CPT es marca registrada de la American
-- Medical Association; para uso productivo se requiere licencia AMA.
-- Code Status: 'Nuevo' = estado CMS A (activo/pagable); 'Revisado' = presente en el
-- archivo con estado no pagable (B,C,E,I,J,N,R,T,X). 'Eliminado' no aplica (archivo 2026).
-- PE RVU: se usa el valor de centro/facility del archivo CMS.
-- =====================================================================

CREATE DATABASE IF NOT EXISTS `coverage_latam` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `coverage_latam`;

DROP TABLE IF EXISTS `latam_cpt`;
CREATE TABLE `latam_cpt` (
  `code` VARCHAR(5) NOT NULL,
  `code_status` ENUM('Nuevo','Revisado','Eliminado') NOT NULL DEFAULT 'Nuevo',
  `short_description` VARCHAR(35) NOT NULL,
  `medium_description` VARCHAR(48) NOT NULL,
  `long_description` TEXT NOT NULL,
  `chapter` VARCHAR(60) NOT NULL,
  `section` VARCHAR(60) NOT NULL,
  `work_rvu` DECIMAL(6,2) NOT NULL DEFAULT 0.00,
  `pe_rvu` DECIMAL(6,2) NOT NULL DEFAULT 0.00,
  `mp_rvu` DECIMAL(6,2) NOT NULL DEFAULT 0.00,
  `lay_terms` TEXT NOT NULL,
  `modifiers` VARCHAR(120) NOT NULL DEFAULT '',
  PRIMARY KEY (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

